import os as _os

def _oracle_write(text):
    _os.write(1, (text + '\n').encode())
import errno
std_c_errors = frozenset(['EDOM', 'ERANGE'])

def _t():
    for error_code in std_c_errors:
        assert hasattr(errno, error_code), ('assertHasAttr', errno, error_code)
try:
    _t()
except BaseException as _e:
    _oracle_write('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    _oracle_write('ok')

