import os as _os

def _oracle_write(text):
    _os.write(1, (text + '\n').encode())
import errno

def _t():
    for attribute in errno.__dict__.keys():
        if attribute.isupper():
            assert getattr(errno, attribute) in errno.errorcode, ('assertIn', getattr(errno, attribute), errno.errorcode)
try:
    _t()
except BaseException as _e:
    _oracle_write('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    _oracle_write('ok')
